.product-item__quick-view--hoverless.btn{
  position:absolute;
  bottom:0;
  right:0;
  padding:calc(4px * 2);
  padding:var(--spacing-2);
  min-width:0;
  min-height:0;
  z-index:2;
}
.product-item__quick-view--hoverless.btn.loading{
    position:absolute;
  }
.product-item__quick-view--hoverless.btn.loading .icon{
      opacity:0.6;
    }
.product-item__quick-view--hoverless.btn .icon-quick-add,
  .product-item__quick-view--hoverless.btn .icon-quick-view{
    width:32px;
    height:32px;
  }
.product-item__quick-view--hoverless.btn .icon-quick-add .quick-shop-circle, .product-item__quick-view--hoverless.btn .icon-quick-view .quick-shop-circle{
      fill:var(--color-background);
    }
@media (min-width: 720px){
.product-item__quick-view--hoverless.btn{
    visibility:hidden
}
  }
.product-item__media{
  position:relative;
  border-radius:var(--corner-radius-cards-and-images);
  overflow:hidden;
}
.product-item__image-link{
  display:block;
  position:relative;
}
.product-item__image--one{
  z-index:2;
}
.product-item__image--two.image{
  position:absolute;
  top:0;
  right:0;
  bottom:0;
  left:0;
  height:100%;
  z-index:2;
  opacity:0;
  transform:scale(1.2);
  background-color:var(--color-background);

  transition:opacity 300ms cubic-bezier(0.33, 0, 0, 1), transform 300ms cubic-bezier(0.33, 0, 0, 1);

  transition:opacity var(--duration-fast) var(--easing), transform var(--duration-fast) var(--easing);
}
.product-item__image--two.image.active{
    transform:scale(1);
    opacity:1;
    transition:opacity 300ms cubic-bezier(0.33, 0, 0, 1), transform 300ms cubic-bezier(0.33, 0, 0, 1), z-index 0ms 300ms linear;
    transition:opacity var(--duration-fast) var(--easing), transform var(--duration-fast) var(--easing), z-index 0ms var(--duration-fast) linear;
  }
@media (hover: none){
    .product-item__image--two.image{
      display:none;
    }
  }
.product-item__meta{
  display:flex;
  flex-wrap:wrap;
  flex-direction:column;
  justify-content:space-between;
}
@media (min-width: 480px){
.product-item__meta{
    flex-wrap:nowrap
}
  }
@media (max-width: 719px){
.product-item__meta .btn[data-quick-shop-trigger]{
      display:none
  }
    }
.product-item__text{
  width:100%;
  margin:calc(4px * 4) auto calc(4px * 2);
  margin:var(--spacing-4) auto var(--spacing-2);
}
.product-item__text > *:not(:empty):not(:last-child){
    margin-bottom:2px;
    margin-bottom:var(--spacing-unit-half);
  }
.product-item__product-vendor,
.product-item__swatch-count{
