  );
  --color-outline-button-outline:var(--color-drawer-outline-button-outline);
  --color-outline-button-outline-alpha-05:var(
    --color-drawer-outline-button-outline-alpha-05
  );
  --color-outline-button-outline-alpha-10:var(
    --color-drawer-outline-button-outline-alpha-10
  );
  --color-outline-button-outline-alpha-60:var(
    --color-drawer-outline-button-outline-alpha-60
  );
